const titleEl=document.querySelector("#article-title"),contentEl=document.querySelector("#article-content"),categoryEl=document.querySelector("#article-category"),dateEl=document.querySelector("#article-date"),footerTitleEl=document.querySelector("#article-footer-title");function formatDate(t){if(!t)return"";const e=new Date(t);return Number.isNaN(e.getTime())?"":e.toLocaleDateString("zh-CN",{year:"numeric",month:"2-digit",day:"2-digit"})}async function loadArticle(){const t=new URLSearchParams(window.location.search).get("id");if(t)try{const e=await fetch(`/api/notion/articles/${t}`),o=await e.json();if(!e.ok)return void(titleEl.textContent=o.error||"文章不存在");const n=o.article;document.title=`Berlin2003 / ${n.title}`,titleEl.textContent=n.title,categoryEl.textContent=n.category?`${n.module} · ${n.category}`:n.module,footerTitleEl.textContent=n.title,dateEl.textContent=formatDate(n.createdAt),contentEl.innerHTML=n.contentHtml||"<p>这篇文章没有内容。</p>"}catch{titleEl.textContent="加载失败"}else titleEl.textContent="缺少文章 ID"}loadArticle();